//! Oracle rows and real packet/producer builders for the pinned scene join (L07-C; D32, G03a).
//!
//! `fixtures/object-scene-producer-pin/oracle.txt` was generated by `tools/gen_oracle.js`
//! from baseline fbe4b8a3: the verbatim layer-level and element-level Order blocks of
//! `buildSceneJson` (src/js/engine-bridge.js) run in a Node `vm` over 300 scenes. Row
//! format: `S id layers expected`; `layers` is `;`-joined `rank:ords` (`-` undefined,
//! `=` no shapes) and `expected` the baseline scene order back to front as
//! `layer.element` labels of natural indices.
//!
//! Each scene becomes a real v2 native document (layers stored in reverse, objects
//! and plan elements stored reversed, so array positions never equal paint order),
//! a real `ObjectFramePacket`, and three producers that claim records by
//! `(layer + element) % 3` and hand them over in reversed encounter order. The joined
//! sequence must equal the baseline scene order.

use super::{join_scene, PinnedScene, ProducerEntry, ProducerOutput, SceneOutcome, ScenePin};
use crate::object_codec::decode_storage_project;
use crate::object_document::FrameScopeKind;
use crate::object_frame_packet::{prepare_object_frame, ObjectFramePacket, ObjectFrameSelector};
use crate::revision::ObjectSnapshot;
use serde_json::{json, Value};

pub(crate) const ORACLE: &str = include_str!("fixtures/object-scene-producer-pin/oracle.txt");
pub(crate) const FRAME: u32 = 7;
pub(crate) const STROKE_IDS: [&str; 4] = ["a", "b", "c", "d"];
pub(crate) const PRODUCERS: [&str; 3] = ["contour", "component", "text"];

/// (layer uid, stroke id, fill.r bits) read from the immutable source record.
pub(crate) type Label = (String, String, u64);

pub(crate) struct LayerSpec {
    pub(crate) rank: Option<f64>,
    pub(crate) ords: Vec<Option<f64>>,
}

pub(crate) struct Case {
    pub(crate) id: String,
    pub(crate) layers: Vec<LayerSpec>,
    pub(crate) expected: Vec<String>,
}

fn token(tok: &str) -> Option<f64> {
    (tok != "-").then(|| tok.parse::<f64>().expect("number token"))
}

pub(crate) fn cases() -> Vec<Case> {
    ORACLE
        .lines()
        .filter(|line| line.starts_with("S "))
        .map(|line| {
            let cols: Vec<&str> = line.split(' ').collect();
            assert_eq!(cols.len(), 4, "{line}");
            let layers = cols[2]
                .split(';')
                .map(|layer| {
                    let (rank, ords) = layer.split_once(':').expect("rank:ords");
                    LayerSpec {
                        rank: token(rank),
                        ords: if ords == "=" {
                            Vec::new()
                        } else {
                            ords.split(',').map(token).collect()
                        },
                    }
                })
                .collect();
            Case {
                id: cols[1].to_owned(),
                layers,
                expected: cols[3].split(',').map(str::to_owned).collect(),
            }
        })
        .collect()
}

/// A hand-written scene without an oracle row.
pub(crate) fn case_of(spec: Vec<(Option<f64>, Vec<Option<f64>>)>) -> Case {
    Case {
        id: "literal".to_owned(),
        layers: spec
            .into_iter()
            .map(|(rank, ords)| LayerSpec { rank, ords })
            .collect(),
        expected: Vec::new(),
    }
}

pub(crate) fn gid_of(case: &Case, layer: usize, element: usize) -> usize {
    case.layers[..layer]
        .iter()
        .map(|spec| spec.ords.len())
        .sum::<usize>()
        + element
}

pub(crate) fn record(layer: &str, id: &str, gid: usize) -> Value {
    json!({"schemaVersion":1,"family":"closed-solid-fill-cubic-path",
        "target":{"contextId":"scene-root","frameScope":{"kind":"authored","frame":FRAME},"layerUid":layer,"strokeId":id},
        "geometry":{"kind":"cubic-path","closed":true,"coordinateSpace":"document-world","handleSpace":"relative",
        "segments":[{"point":{"x":0,"y":0},"handleIn":{"x":0,"y":0},"handleOut":{"x":1,"y":0}},
        {"point":{"x":10,"y":10},"handleIn":{"x":0,"y":-1},"handleOut":{"x":0,"y":0}}]},
        "fill":{"kind":"solid","r":(gid as f64 + 1.0) / 100.0,"g":0,"b":0,"a":0.75}})
}

fn order_json(value: Option<f64>) -> Value {
    match value {
        Some(number) => json!({ "static": [number] }),
        None => json!({}),
    }
}

/// Layers `L{j}` and elements `a..d`; document layers, objects and plan elements are
/// stored reversed. `hidden` lists layers stored with `visible: false`.
pub(crate) fn document(case: &Case, hidden: &[usize]) -> Value {
    let mut objects = Vec::new();
    let mut elements = Vec::new();
    let mut gid = 0;
    for (j, layer) in case.layers.iter().enumerate() {
        for (k, ord) in layer.ords.iter().enumerate() {
            let uid = format!("L{j}");
            objects.push(record(&uid, STROKE_IDS[k], gid));
            elements.push(json!({"layerUid":uid,"strokeId":STROKE_IDS[k],"naturalPosition":k,"order":order_json(*ord)}));
            gid += 1;
        }
    }
    objects.reverse();
    elements.reverse();
    let layers: Vec<Value> = (0..case.layers.len())
        .rev()
        .map(|j| {
            let mut layer = json!({ "layerUid": format!("L{j}") });
            if hidden.contains(&j) {
                layer["visible"] = json!(false);
            }
            layer
        })
        .collect();
    let plan_layers: Vec<Value> = case
        .layers
        .iter()
        .enumerate()
        .map(|(j, layer)| json!({"layerUid":format!("L{j}"),"naturalPosition":j,"order":order_json(layer.rank)}))
        .collect();
    json!({"format":"nemo.native-object-document","formatVersion":2,"totalFrames":21,
        "layers":layers,"objects":objects,
        "compositionOrder":{"format":"nemo.native-object-order-plan","formatVersion":1,"documentFormatVersion":2,
        "contexts":[{"contextId":"scene-root","layers":plan_layers,
        "scopes":[{"frameScope":{"kind":"authored","frame":FRAME},"elements":elements}]}],
        "migration":"explicit-plan-required","referencePolicy":"unresolved"}})
}

pub(crate) fn snapshot(value: &Value, instance: &str) -> ObjectSnapshot {
    ObjectSnapshot::new(
        instance,
        decode_storage_project(&serde_json::to_vec(value).unwrap()).unwrap(),
    )
    .unwrap()
}

pub(crate) fn packet(snapshot: &ObjectSnapshot) -> ObjectFramePacket {
    prepare_object_frame(
        snapshot,
        &ObjectFrameSelector {
            instance_id: snapshot.instance_id(),
            document_id: snapshot.document_id(),
            content_revision: snapshot.content_revision(),
            document_snapshot_id: snapshot.snapshot_id(),
            context_id: "scene-root",
            scope_kind: FrameScopeKind::Authored,
            frame: FRAME,
        },
    )
    .unwrap()
}

/// `layer.element` of a label's natural indices, e.g. `("L2", "b", _)` -> `2.1`.
pub(crate) fn label_of(layer_uid: &str, stroke_id: &str) -> String {
    format!("{}.{}", &layer_uid[1..], stroke_id.as_bytes()[0] - b'a')
}

/// Three producers over the packet's real selected records. Record `(j, k)` goes to
/// producer `(j + k) % 3`; entries are pushed in DESCENDING `(j, k)` and the output
/// list is handed over reversed, so encounter order never equals scene order.
pub(crate) fn outputs(packet: &ObjectFramePacket) -> Vec<ProducerOutput<Label>> {
    let pin = ScenePin::of_packet(packet);
    let mut outs: Vec<ProducerOutput<Label>> = PRODUCERS
        .iter()
        .map(|name| {
            ProducerOutput::new(*name, pin.clone())
                .with_resource(format!("res:{name}"), "v1")
                .with_resource("shared", "7")
        })
        .collect();
    let mut rows: Vec<(usize, usize, usize, Label)> = packet
        .records()
        .map(|entry| {
            let target = entry.record().target();
            let j = target.layer_uid()[1..].parse::<usize>().unwrap();
            let k = usize::from(target.stroke_id().as_bytes()[0] - b'a');
            let bits = entry
                .record()
                .solid_fill()
                .unwrap()
                .r
                .as_f64()
                .unwrap()
                .to_bits();
            (
                j,
                k,
                entry.source_object_index(),
                (
                    target.layer_uid().to_owned(),
                    target.stroke_id().to_owned(),
                    bits,
                ),
            )
        })
        .collect();
    rows.sort_by(|a, b| (b.0, b.1).cmp(&(a.0, a.1)));
    for (j, k, index, label) in rows {
        outs[(j + k) % 3].entries.push(ProducerEntry::Item {
            source_object_index: index,
            payload: label,
        });
    }
    outs.reverse();
    outs
}

pub(crate) fn labels(scene: &PinnedScene<Label>) -> Vec<String> {
    scene
        .entries()
        .iter()
        .map(|entry| match entry.outcome() {
            SceneOutcome::Item { payload, .. } => label_of(&payload.0, &payload.1),
            SceneOutcome::Unavailable(_) => format!("unavailable:{}", entry.source_object_index()),
        })
        .collect()
}

pub(crate) fn join_case(case: &Case) -> Vec<String> {
    let snap = snapshot(&document(case, &[]), "scene-pin");
    let pk = packet(&snap);
    let scene = join_scene(&pk, &ScenePin::of_packet(&pk), outputs(&pk)).expect("join");
    labels(&scene)
}

/// Ids of the rows whose joined order differs from the stored expectation.
pub(crate) fn divergences(cases: &[Case]) -> Vec<String> {
    cases
        .iter()
        .filter(|case| join_case(case) != case.expected)
        .map(|case| case.id.clone())
        .collect()
}
